let products=[],category='all',order='default';
const grid=document.querySelector('#products'),dialog=document.querySelector('#product-dialog');
const categoryNames={'chess-clocks':'Chess clocks','chess-boards':'Boards & sets','chess-merchandise':'Merchandise','special-offers':'Special offers'};
const money=n=>new Intl.NumberFormat('en-EG').format(n)+' EGP';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cat=p=>categoryNames[p.categories.find(c=>categoryNames[c])]||'The collection';
const price=p=>`<div class="price"><span>${money(p.price)}</span>${p.oldPrice&&p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</div>`;
function visible(){let items=products.filter(p=>category==='all'||p.categories.includes(category));if(order==='low')items.sort((a,b)=>a.price-b.price);if(order==='high')items.sort((a,b)=>b.price-a.price);if(order==='name')items.sort((a,b)=>a.name.localeCompare(b.name));return items;}
function render(){const items=visible();grid.innerHTML=items.map(p=>{const i=products.indexOf(p);return `<article class="product"><button class="image-button" data-product="${i}" aria-label="View ${escape(p.name)}">${p.oldPrice>p.price?`<span class="sale">SAVE ${Math.round((1-p.price/p.oldPrice)*100)}%</span>`:''}<img src="${escape(p.image)}" alt="${escape(p.name)}" loading="lazy" width="500" height="500"></button><div class="card-meta"><div><p class="category">${cat(p)}</p><h3><button class="name-button" data-product="${i}">${escape(p.name)}</button></h3></div><button class="card-arrow" data-product="${i}" aria-label="View ${escape(p.name)}">↗</button></div>${price(p)}<button class="add-to-cart" data-add="${i}">Add to cart <span aria-hidden="true">+</span></button></article>`}).join('')||'<p class="loading">No products in this category.</p>';document.querySelector('#count').textContent=`${items.length} products`;document.querySelectorAll('[data-category]').forEach(b=>{const yes=b.dataset.category===category;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});return items;}
function filter(value){if(!['all',...Object.keys(categoryNames)].includes(value))throw new Error('Unknown category');category=value;return render();}
function openProduct(i){const p=products[i];if(!p)throw new Error('Unknown product');document.querySelector('#detail-name').textContent=p.name;document.querySelector('#detail-category').textContent=cat(p);document.querySelector('#detail-price').innerHTML=price(p);document.querySelector('#detail-description').textContent=p.description;const img=document.querySelector('#detail-image');img.src=p.image;img.alt=p.name;document.querySelector('#order-link').onclick=()=>{window.AdlyCart.add(p);dialog.close();window.AdlyCart.open();};const photos=[...new Set([p.image,...p.images])].filter(Boolean);document.querySelector('#thumbnails').innerHTML=photos.length>1?photos.map((src,i)=>`<button data-photo="${escape(src)}" class="${i===0?'selected':''}" aria-label="View product image ${i+1}"><img src="${escape(src)}" alt=""></button>`).join(''):'';dialog.showModal();return p;}
document.querySelector('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b)filter(b.dataset.category)});
document.querySelector('#sort').addEventListener('change',e=>{order=e.target.value;render()});
grid.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){window.AdlyCart.add(products[Number(add.dataset.add)]);return;}const b=e.target.closest('[data-product]');if(b)openProduct(Number(b.dataset.product))});
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#thumbnails').addEventListener('click',e=>{const b=e.target.closest('[data-photo]');if(!b)return;document.querySelector('#detail-image').src=b.dataset.photo;document.querySelectorAll('[data-photo]').forEach(n=>n.classList.toggle('selected',n===b))});
fetch('/products.json').then(r=>{if(!r.ok)throw new Error();return r.json()}).then(data=>{products=data.map(p=>({...p,image:'/'+p.image.replace(/^\/+/,''),images:p.images.map(u=>'/'+u.replace(/^\/+/ ,''))}));render();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_products',title:'Filter Adly products',description:'Filter the visible shop collection by category. Does not place an order.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['all',...Object.keys(categoryNames)]}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.category!=='string')throw new Error('Category is required');return {products:filter(input.category).map(p=>({name:p.name,price:p.price,currency:'EGP'}))}}})).catch(()=>{});}catch{}}}).catch(()=>{grid.innerHTML='<p class="loading">The collection could not load. <a href="/shop/">Reload the collection</a></p>';document.querySelector('#count').textContent='Collection unavailable'});
